class StandardMinesweeperAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed=seed)

    def opening_action(self, game, grid, rows, cols):
        cr, cc = rows // 2, cols // 2
        best = None
        best_dist = float('inf')
        for r in range(rows):
            for c in range(cols):
                cell = grid[r][c]
                if not cell.is_revealed and not cell.is_flagged:
                    dist = (r - cr) ** 2 + (c - cc) ** 2
                    if dist < best_dist or (dist == best_dist and self._rng.random() < 0.5):
                        best_dist = dist
                        best = (r, c)
        if best:
            return ('reveal', best[0], best[1])
        return ('reveal', rows // 2, cols // 2)

    def frontier_cell_score(self, game, grid, pos, prob_map, mine_set, neighbors_of):
        r, c = pos
        p = prob_map.get(pos, 0.5)
        nbrs = neighbors_of.get((r, c), [])
        suspected = sum(
            1 for nr, nc in nbrs
            if (nr, nc) in mine_set or prob_map.get((nr, nc), 0.0) >= 0.5
        )
        unrevealed_neighbors = sum(
            1 for nr, nc in nbrs
            if not grid[nr][nc].is_revealed and not grid[nr][nc].is_flagged
        )
        return (p, suspected, -unrevealed_neighbors, self._rng.random())

class TelegraphDecodingAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed=seed)

    def clue_value(self, game, grid, r, c):
        cell = grid[r][c]
        if not cell.is_revealed:
            return None
        raw = cell.adjacent_mines
        true_count = raw % 10
        return true_count

    def postprocess_prob_map(self, game, grid, prob_map, mine_set, neighbors_of):
        rows = game.get_config().rows
        cols = game.get_config().cols

        for r in range(rows):
            for c in range(cols):
                cell = grid[r][c]
                if not cell.is_revealed:
                    continue
                raw = cell.adjacent_mines
                true_count = raw % 10
                tele_count = raw // 10
                if tele_count == 0:
                    continue
                neighbors = neighbors_of.get((r, c), [])
                unrevealed_unflagged = [
                    (nr, nc) for nr, nc in neighbors
                    if not grid[nr][nc].is_revealed and not grid[nr][nc].is_flagged
                ]
                already_flagged = sum(
                    1 for nr, nc in neighbors if grid[nr][nc].is_flagged
                )
                remaining_true = true_count - already_flagged
                if len(unrevealed_unflagged) == 0:
                    continue
                if tele_count == len(unrevealed_unflagged):
                    for pos in unrevealed_unflagged:
                        if pos not in mine_set:
                            mine_set.add(pos)
                            prob_map[pos] = 1.0
                if remaining_true == 0 and tele_count > 0:
                    telegraphing_neighbors = [
                        pos for pos in unrevealed_unflagged
                        if prob_map.get(pos, 0.5) >= 0.8
                    ]
                    non_telegraphing = [
                        pos for pos in unrevealed_unflagged
                        if pos not in telegraphing_neighbors
                    ]
                    for pos in non_telegraphing:
                        if pos not in mine_set:
                            prob_map[pos] = max(0.0, prob_map.get(pos, 0.5) * 0.3)
                if tele_count > 0 and remaining_true == tele_count:
                    for pos in unrevealed_unflagged:
                        if pos not in mine_set:
                            prob_map[pos] = max(prob_map.get(pos, 0.5), 0.85)
                            mine_set.add(pos)

        return prob_map

class VonNeumannMinesweeperAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed=seed)

    def neighbor_positions(self, game, r, c, rows, cols):
        return game.board.neighbors(r, c)

    def frontier_cell_score(self, game, grid, pos, prob_map, mine_set, neighbors_of):
        r, c = pos
        p = prob_map.get(pos, 0.5)
        neighbors = neighbors_of.get((r, c), [])
        revealed_neighbors = sum(
            1 for nr, nc in neighbors
            if grid[nr][nc].is_revealed and not grid[nr][nc].is_mine
        )
        flagged_neighbors = sum(
            1 for nr, nc in neighbors
            if grid[nr][nc].is_flagged or (nr, nc) in mine_set
        )
        info_potential = revealed_neighbors - flagged_neighbors
        return (p, -info_potential, self._rng.random())

class ParityMooreAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed=seed)

    def neighbor_positions(self, game, r, c, rows, cols):
        return game.board.neighbors(r, c)

    def clue_value(self, game, grid, r, c):
        cell = grid[r][c]
        if not cell.is_revealed or cell.is_mine:
            return None
        return cell.adjacent_mines

    def postprocess_prob_map(self, game, grid, prob_map, mine_set, neighbors_of):
        rows = len(grid)
        cols = len(grid[0]) if rows > 0 else 0
        parity_votes = {}
        for r in range(rows):
            for c in range(cols):
                cell = grid[r][c]
                if not cell.is_revealed or cell.is_mine:
                    continue
                true_count = cell.adjacent_mines
                parity = true_count % 2
                nbrs = neighbors_of.get((r, c), game.board.neighbors(r, c))
                unknown_nbrs = [
                    pos for pos in nbrs
                    if not grid[pos[0]][pos[1]].is_revealed
                    and not grid[pos[0]][pos[1]].is_flagged
                    and pos not in mine_set
                ]
                flagged_count = sum(
                    1 for pos in nbrs
                    if grid[pos[0]][pos[1]].is_flagged or pos in mine_set
                )
                effective_parity = (parity - flagged_count) % 2
                if len(unknown_nbrs) == 0:
                    continue
                est_mine_sum = sum(prob_map.get(pos, 0.5) for pos in unknown_nbrs)
                for pos in unknown_nbrs:
                    p = prob_map.get(pos, 0.5)
                    if len(unknown_nbrs) == 1:
                        if effective_parity == 1:
                            parity_votes[pos] = parity_votes.get(pos, []) + [0.9]
                        else:
                            parity_votes[pos] = parity_votes.get(pos, []) + [0.05]
                    else:
                        if effective_parity == 1 and est_mine_sum < 0.5:
                            parity_votes[pos] = parity_votes.get(pos, []) + [min(p + 0.1, 0.95)]
                        elif effective_parity == 0 and est_mine_sum > len(unknown_nbrs) - 0.5:
                            parity_votes[pos] = parity_votes.get(pos, []) + [max(p - 0.1, 0.05)]
                        else:
                            parity_votes[pos] = parity_votes.get(pos, []) + [p]
        adjusted = dict(prob_map)
        for pos, votes in parity_votes.items():
            if pos in adjusted:
                avg = sum(votes) / len(votes)
                adjusted[pos] = 0.5 * adjusted[pos] + 0.5 * avg
        return adjusted

class ParityMooreAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed)

    def clue_value(self, game, grid, r, c):
        cell = grid[r][c]
        if not cell.is_revealed or cell.is_mine:
            return None
        return cell.adjacent_mines

    def postprocess_prob_map(self, game, grid, prob_map, mine_set, neighbors_of):
        rows = game.get_config().rows
        cols = game.get_config().cols

        for iteration in range(3):
            updated = False
            for r in range(rows):
                for c in range(cols):
                    cell = grid[r][c]
                    if not cell.is_revealed or cell.is_mine:
                        continue
                    parity = cell.adjacent_mines % 2
                    nbrs = neighbors_of.get((r, c), [])
                    flagged = [(nr, nc) for nr, nc in nbrs if grid[nr][nc].is_flagged]
                    in_mine_set = [(nr, nc) for nr, nc in nbrs if (nr, nc) in mine_set and not grid[nr][nc].is_flagged]
                    unknown = [(nr, nc) for nr, nc in nbrs if not grid[nr][nc].is_revealed and not grid[nr][nc].is_flagged and (nr, nc) not in mine_set]
                    known_mine_count = len(flagged) + len(in_mine_set)
                    remaining_parity = (parity - known_mine_count) % 2
                    if len(unknown) == 0:
                        continue
                    if len(unknown) == 1:
                        pos = unknown[0]
                        if remaining_parity == 1:
                            if pos not in mine_set:
                                mine_set.add(pos)
                                prob_map[pos] = 1.0
                                updated = True
                        else:
                            if prob_map.get(pos, 0.5) > 0.01:
                                prob_map[pos] = max(0.0, prob_map.get(pos, 0.5) * 0.1)
                                updated = True
                    else:
                        for pos in unknown:
                            current = prob_map.get(pos, 0.5)
                            if remaining_parity == 1:
                                adjusted = min(1.0, current * 1.15)
                            else:
                                adjusted = max(0.0, current * 0.85)
                            if abs(adjusted - current) > 0.001:
                                prob_map[pos] = adjusted
                                updated = True
            if not updated:
                break

        return prob_map

    def opening_action(self, game, grid, rows, cols):
        zone_rows = 4
        zone_cols = 4
        num_zr = (rows + zone_rows - 1) // zone_rows
        num_zc = (cols + zone_cols - 1) // zone_cols
        for zi in range(num_zr):
            for zj in range(num_zc):
                r_start = zi * zone_rows
                r_end = min(r_start + zone_rows, rows)
                c_start = zj * zone_cols
                c_end = min(c_start + zone_cols, cols)
                zone_satisfied = False
                for r in range(r_start, r_end):
                    for c in range(c_start, c_end):
                        if grid[r][c].is_revealed and not grid[r][c].is_mine:
                            zone_satisfied = True
                            break
                    if zone_satisfied:
                        break
                if not zone_satisfied:
                    cr = (r_start + r_end) // 2
                    cc = (c_start + c_end) // 2
                    if not grid[cr][cc].is_revealed:
                        return ("reveal", cr, cc)
        mid_r = rows // 2
        mid_c = cols // 2
        return ("reveal", mid_r, mid_c)

class RippleCascadeZoneCoverageAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed)
        self._last_click = None

    def neighbor_positions(self, game, r, c, rows, cols):
        return game.board.neighbors(r, c)

    def opening_action(self, game, grid, rows, cols):
        best = None
        best_score = -1
        for r in range(rows):
            for c in range(cols):
                cell = grid[r][c]
                if cell.is_revealed or cell.is_mine or cell.is_flagged:
                    continue
                zone_r = r // 4
                zone_c = c // 4
                num_zr = (rows + 3) // 4
                num_zc = (cols + 3) // 4
                corner_dist = min(r, rows - 1 - r) + min(c, cols - 1 - c)
                center_dist = abs(r - rows // 2) + abs(c - cols // 2)
                score = center_dist + self._rng.random() * 0.1
                if score > best_score:
                    best_score = score
                    best = (r, c)
        if best:
            self._last_click = best
            return ("reveal", best[0], best[1])
        return ("reveal", rows // 2, cols // 2)

    def _zone_satisfied(self, grid, rows, cols):
        num_zr = (rows + 3) // 4
        num_zc = (cols + 3) // 4
        satisfied = set()
        for r in range(rows):
            for c in range(cols):
                cell = grid[r][c]
                if cell.is_revealed and not cell.is_mine:
                    zi = r // 4
                    zj = c // 4
                    satisfied.add((zi, zj))
        all_zones = set()
        for zi in range(num_zr):
            for zj in range(num_zc):
                all_zones.add((zi, zj))
        return satisfied, all_zones

    def frontier_cell_score(self, game, grid, pos, prob_map, mine_set, neighbors_of):
        r, c = pos
        rows = game.get_config().rows
        cols = game.get_config().cols
        p = prob_map.get(pos, 0.5)

        satisfied_zones, all_zones = self._zone_satisfied(grid, rows, cols)
        unsatisfied = all_zones - satisfied_zones
        zi = r // 4
        zj = c // 4
        in_unsatisfied_zone = 1 if (zi, zj) in unsatisfied else 0

        if self._last_click is not None:
            lr, lc = self._last_click
            dist = abs(r - lr) + abs(c - lc)
        else:
            dist = 0

        far_bonus = 0.0
        if dist >= 3:
            far_bonus = min(0.15, dist * 0.02)

        zone_bonus = 0.1 if in_unsatisfied_zone else 0.0

        adjusted_p = p - far_bonus - zone_bonus

        return (adjusted_p, -in_unsatisfied_zone, -dist, self._rng.random())

    def postprocess_prob_map(self, game, grid, prob_map, mine_set, neighbors_of):
        rows = game.get_config().rows
        cols = game.get_config().cols
        satisfied_zones, all_zones = self._zone_satisfied(grid, rows, cols)
        unsatisfied = all_zones - satisfied_zones
        if not unsatisfied:
            return prob_map
        adjusted = dict(prob_map)
        for pos, p in prob_map.items():
            r, c = pos
            zi = r // 4
            zj = c // 4
            if (zi, zj) in unsatisfied:
                adjusted[pos] = max(0.0, p - 0.05)
        return adjusted

class ParityTelegraphMinesweeperAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed=seed)

    def clue_value(self, game, grid, r, c):
        cell = grid[r][c]
        if not cell.is_revealed:
            return None
        raw = cell.adjacent_mines
        true_count = raw % 10
        telegraph_count = raw // 10
        return true_count + telegraph_count

    def postprocess_prob_map(self, game, grid, prob_map, mine_set, neighbors_of):
        rows = game.get_config().rows
        cols = game.get_config().cols
        telegraph_boost = {}
        for r in range(rows):
            for c in range(cols):
                cell = grid[r][c]
                if not cell.is_revealed:
                    continue
                raw = cell.adjacent_mines
                telegraph_count = raw // 10
                if telegraph_count > 0:
                    neighbors = neighbors_of.get((r, c), [])
                    unrevealed = [
                        (nr, nc) for nr, nc in neighbors
                        if not grid[nr][nc].is_revealed and not grid[nr][nc].is_flagged
                    ]
                    for pos in unrevealed:
                        if pos not in mine_set:
                            current = telegraph_boost.get(pos, 0.0)
                            telegraph_boost[pos] = max(current, telegraph_count / max(len(unrevealed), 1))
        updated = dict(prob_map)
        for pos, boost in telegraph_boost.items():
            if pos in updated:
                p = updated[pos]
                updated[pos] = min(0.99, p + (1.0 - p) * boost * 0.5)
            else:
                updated[pos] = min(0.99, boost * 0.5)
        return updated

class ParityMooreAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed=seed)

    def neighbor_positions(self, game, r, c, rows, cols):
        return list(game.board.neighbors(r, c))

    def clue_value(self, game, grid, r, c):
        cell = grid[r][c]
        if not cell.is_revealed or cell.is_mine:
            return None
        return cell.adjacent_mines

    def postprocess_prob_map(self, game, grid, prob_map, mine_set, neighbors_of):
        rows = len(grid)
        cols = len(grid[0]) if rows > 0 else 0

        for r in range(rows):
            for c in range(cols):
                cell = grid[r][c]
                if not cell.is_revealed or cell.is_mine:
                    continue
                true_count = cell.adjacent_mines
                parity = true_count % 2
                nbrs = neighbors_of.get((r, c), [])
                unknown_nbrs = [
                    pos for pos in nbrs
                    if not grid[pos[0]][pos[1]].is_revealed
                    and not grid[pos[0]][pos[1]].is_flagged
                ]
                flagged_count = sum(
                    1 for pos in nbrs
                    if grid[pos[0]][pos[1]].is_flagged or pos in mine_set
                )
                remaining_parity = (parity - flagged_count) % 2
                if len(unknown_nbrs) == 1:
                    pos = unknown_nbrs[0]
                    if remaining_parity == 1:
                        prob_map[pos] = max(prob_map.get(pos, 0.5), 0.95)
                    else:
                        prob_map[pos] = min(prob_map.get(pos, 0.5), 0.05)
                elif len(unknown_nbrs) == 2:
                    p0 = unknown_nbrs[0]
                    p1 = unknown_nbrs[1]
                    if remaining_parity == 0:
                        avg = (prob_map.get(p0, 0.5) + prob_map.get(p1, 0.5)) / 2.0
                        prob_map[p0] = avg
                        prob_map[p1] = avg
                    else:
                        v0 = prob_map.get(p0, 0.5)
                        v1 = prob_map.get(p1, 0.5)
                        combined = v0 + v1
                        if combined > 0:
                            prob_map[p0] = v0 / combined if combined > 0 else 0.5
                            prob_map[p1] = v1 / combined if combined > 0 else 0.5

        return prob_map
